def place(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]}).body["order_id"]


def test_unknown_customer(shop):
    response = shop.insights.handle_order_history("nope")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_no_orders(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_newest_first_with_discount_and_cancelled(shop):
    first = place(shop, "c1", ("LAMP", 2))
    second = place(shop, "c1", ("BOOK", 1))
    third = place(shop, "c1", ("PEN", 2))
    place(shop, "c2", ("PEN", 1))
    shop.orders.handle_cancel(second)
    body = shop.insights.handle_order_history("c1").body
    assert body["customer_id"] == "c1"
    assert [o["order_id"] for o in body["orders"]] == [third, second, first]
    assert body["orders"][1]["status"] == "cancelled"
    assert body["orders"][0]["status"] != "cancelled"
    for entry in body["orders"]:
        assert entry["total_cents"] == shop.orders.handle_get(entry["order_id"]).body["total_cents"]
    assert body["orders"][2]["total_cents"] == 10800


def test_top_customers_rejects_bad_limit(shop):
    for bad in (0, -1, True, "3", None, 1.5):
        response = shop.insights.handle_top_customers(bad)
        assert response.status == 400
        assert "error" in response.body


def test_top_customers_ranking_limit_and_zero_exclusion(shop):
    shop.customers.handle_register({"customer_id": "c0", "name": "Zero", "email": "z@example.com"})
    shop.customers.handle_register({"customer_id": "c3", "name": "Tie", "email": "t@example.com"})
    place(shop, "c1", ("PEN", 2))  # 600
    place(shop, "c2", ("BOOK", 1))  # 2500
    place(shop, "c3", ("PEN", 2))  # 600, ties with c1
    cancelled = place(shop, "c0", ("LAMP", 1))
    shop.orders.handle_cancel(cancelled)  # c0 stays at 0
    body = shop.insights.handle_top_customers(10).body
    assert body == {"customers": [
        {"customer_id": "c2", "name": "Grace", "lifetime_value_cents": 2500},
        {"customer_id": "c1", "name": "Ada", "lifetime_value_cents": 600},
        {"customer_id": "c3", "name": "Tie", "lifetime_value_cents": 600},
    ]}
    limited = shop.insights.handle_top_customers(2).body["customers"]
    assert [c["customer_id"] for c in limited] == ["c2", "c1"]


def test_top_customers_empty(shop):
    assert shop.insights.handle_top_customers(5).body == {"customers": []}


def test_lifetime_value_unknown_customer(shop):
    response = shop.insights.handle_lifetime_value("nope")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_no_orders(shop):
    assert shop.insights.handle_lifetime_value("c1").body == {
        "customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_and_uses_discounted_totals(shop):
    place(shop, "c1", ("LAMP", 2))  # 12000 - 1200 discount = 10800
    cancelled = place(shop, "c1", ("LAMP", 1))
    place(shop, "c1", ("PEN", 2))  # 600
    place(shop, "c2", ("PEN", 1))
    shop.orders.handle_cancel(cancelled)
    assert shop.insights.handle_lifetime_value("c1").body == {
        "customer_id": "c1", "order_count": 2, "lifetime_value_cents": 11400}
